# 所有章节的扁平列表（用于搜索）
def get_all_sections():
    """获取所有章节的扁平列表"""
    result = []
    for cat_name, sections_list in MANUAL_CATEGORIES:
        for sec_name, sec_content in sections_list:
            result.append({
                "category": cat_name,
                "title": sec_name,
                "content": sec_content
            })
    return result

def search_manual(keyword):
    """搜索说明书内容"""
    if not keyword or not keyword.strip():
        return []
    keyword = keyword.strip().lower()
    results = []
    for sec in get_all_sections():
        if keyword in sec["title"].lower() or keyword in sec["content"].lower():
            results.append(sec)
    return results
